select s.id snapshot_id,s.job_id,s.race_date,s.track,s.race_no,s.captured_at,s.post_time,s.capture_sha256,s.draft_order,s.proposed_order,p.id prediction_id,p.frozen_at,p.protocol_version,j.job_status,(s.captured_at<=p.frozen_at) capture_before_frozen,(p.frozen_at<s.post_time-interval '3 minutes') frozen_before_cutoff,jsonb_typeof(p.payload) payload_type,(select array_agg(k order by k) from jsonb_object_keys(p.payload) k) payload_keys from private.lab_rank_shadow_preflight_v1 s join public.official_predictions p on (p.race_date,p.track,p.race_no,p.circuit)=(s.race_date,s.track,s.race_no,'JRA') and p.status='FROZEN' join public.jra_prediction_jobs j on j.id=s.job_id where s.circuit='JRA' and s.race_date between '2026-10-17' and '2026-11-15' order by s.race_date desc,s.track,s.race_no limit 2
